1	// Mock API layer for the DOWNLOADABLE VISUAL BUILD only.
2	//
3	// This module is imported by main.tsx ONLY when the app is built with
4	// VITE_MOCK=1. It seeds a fake authenticated session and overrides window.fetch
5	// so every /api/... call resolves with canned demo data — no backend required.
6	// The result is a static bundle that *looks* like the live, logged-in app.
7	//
8	// It is a no-op in normal dev/prod builds. Delete client/src/mocks to remove.
