12	/* ---- base64url + fake JWT --------------------------------------------- */
13	// getCurrentMerchantId() in lib/auth.ts decodes authToken as a JWT and reads
14	// payload.merchantId, so the seed token must be a real base64url JWT.
15	function b64url(obj: unknown): string {
16	  return btoa(JSON.stringify(obj)).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
17	}
18	function fakeJwt(): string {
19	  const header = b64url({ alg: 'HS256', typ: 'JWT' });
20	  const payload = b64url({
21	    userId: 1,
22	    merchantId: MERCHANT_ID,
23	    role: 'merchant',
24	    email: 'demo@harboursidecafe.co.nz',
25	    onboardingCompleted: true,
26	    exp: Math.floor(Date.now() / 1000) + 60 * 60 * 24 * 365,
27	  });
28	  return `${header}.${payload}.mocksignature`;
29	}
