82	function buildTransactions() {
83	  const txns: any[] = [];
84	  let id = 1000;
85	  // ~9 transactions/day for the last 30 days, weighted to daytime.
86	  for (let d = 29; d >= 0; d--) {
87	    const count = 6 + Math.floor(seeded(d) * 8);
88	    for (let i = 0; i < count; i++) {
89	      const hour = 7 + Math.floor(seeded(d * 31 + i) * 11); // 7am–6pm
90	      const min = Math.floor(seeded(d * 7 + i * 3) * 60);
91	      const ts = now - d * DAY;
92	      const created = new Date(ts);
93	      created.setHours(hour, min, 0, 0);
94	      const base = seeded(id);
95	      const price = (4 + base * 42).toFixed(2); // $4–$46
96	      // ~92% completed, small tail of other states
97	      const roll = seeded(id * 3);
98	      const status = roll > 0.94 ? 'refunded' : roll > 0.90 ? 'failed' : roll > 0.87 ? 'pending' : 'completed';
99	      txns.push({
100	        id: id,
101	        merchantId: MERCHANT_ID,
102	        itemName: ITEMS[Math.floor(seeded(id * 5) * ITEMS.length)],
103	        price,
104	        status,
105	        paymentMethod: METHODS[Math.floor(seeded(id * 9) * METHODS.length)],
106	        windcaveFeeRate: '0.0290',
107	        platformFeeRate: '0.0020',
108	        merchantNet: (parseFloat(price) * 0.978).toFixed(2),
109	        totalRefunded: status === 'refunded' ? price : '0.00',
110	        isSplit: false,
111	        totalSplits: 1,
112	        completedSplits: status === 'completed' ? 1 : 0,
113	        createdAt: created.toISOString(),
114	      });
115	      id++;
116	    }
117	  }
118	  return txns.sort((a, b) => +new Date(b.createdAt) - +new Date(a.createdAt));
119	}
