129	function buildAnalytics() {
130	  const completed = TRANSACTIONS.filter(t => t.status === 'completed');
131	  const totalRevenue = completed.reduce((s, t) => s + parseFloat(t.price), 0);
132	  const weekAgo = now - 7 * DAY;
133	  const weekly = completed.filter(t => +new Date(t.createdAt) >= weekAgo);
134	  const weeklyRevenue = weekly.reduce((s, t) => s + parseFloat(t.price), 0);
135	  const currentProviderCost = totalRevenue * 0.029;
136	  const ourCost = totalRevenue * 0.002;
137	  return {
138	    totalTransactions: TRANSACTIONS.length,
139	    completedTransactions: completed.length,
140	    totalRevenue: Math.round(totalRevenue * 100) / 100,
141	    currentProviderCost: Math.round(currentProviderCost * 100) / 100,
142	    ourCost: Math.round(ourCost * 100) / 100,
143	    savings: Math.round((currentProviderCost - ourCost) * 100) / 100,
144	    currentProviderRate: 0.029,
145	    ourRate: 0.002,
146	    weeklyTransactions: weekly.length,
147	    weeklyRevenue: Math.round(weeklyRevenue * 100) / 100,
148	    averageTransaction: completed.length ? Math.round((totalRevenue / completed.length) * 100) / 100 : 0,
149	  };
