import { chromium } from 'playwright';
const BASE = 'http://localhost:4477';
const EXEC = '/nix/store/zi4f80l169xlmivz8vja8wlphq74qqk0-chromium-125.0.6422.141/bin/chromium';

const PAGES = [
  '/dashboard', '/transactions', '/stock', '/settings',
  '/property', '/property/tenants', '/property/tenants/1', '/property/analytics',
  '/trades', '/trades/clients', '/trades/clients/1', '/trades/analytics',
];

const browser = await chromium.launch({ executablePath: EXEC, args: ['--no-sandbox'] });
const ctx = await browser.newContext({ viewport: { width: 430, height: 900 } });
const errors = [];
for (const path of PAGES) {
  const page = await ctx.newPage();
  const pageErrs = [];
  page.on('pageerror', e => pageErrs.push(String(e).split('\n')[0]));
  page.on('console', m => { if (m.type() === 'error') pageErrs.push('console: ' + m.text().slice(0, 120)); });
  await page.goto(BASE + path, { waitUntil: 'networkidle', timeout: 20000 }).catch(e => pageErrs.push('goto: ' + e.message));
  await page.waitForTimeout(700);
  const text = (await page.evaluate(() => document.body.innerText).catch(() => '')) || '';
  const len = text.replace(/\s+/g, ' ').trim().length;
  const flag = len < 200 ? ' <-- THIN' : '';
  const errFlag = pageErrs.length ? '  ERR:' + pageErrs.slice(0, 2).join(' | ') : '';
  console.log(`${path.padEnd(28)} ${String(len).padStart(5)}${flag}${errFlag}`);
  await page.close();
}
await browser.close();

