// Demo/visual build serves as static files with no server-side SPA fallback,
// so it must not depend on the host rewriting deep paths (e.g. /trades) to
// index.html. Hash routing (#/trades) keeps every route 100% client-side, so
// navigation works on any static host, a subpath, or file://.
const IS_MOCK = import.meta.env.VITE_MOCK === "1";

function AppRoutes() {
  return (
    <>
      <Router />
      <BottomNavigation />
    </>
  );
}

function App() {
  return (
    <QueryClientProvider client={queryClient}>
      <TooltipProvider>
        <NotificationProvider>
          <AuthProvider>
            <Toaster />
            {IS_MOCK ? (
              <WouterRouter hook={useHashLocation}>
                <AppRoutes />
              </WouterRouter>
            ) : (
              <AppRoutes />
            )}
          </AuthProvider>
        </NotificationProvider>
      </TooltipProvider>
    </QueryClientProvider>
  );
}

