import { readFile } from 'fs/promises';
import { existsSync, statSync } from 'fs';
import { extname, join, normalize } from 'path';
const ROOT = process.argv[2];
const PORT = 4478;
const TYPES = { '.html':'text/html','.js':'text/javascript','.css':'text/css','.json':'application/json','.png':'image/png','.svg':'image/svg+xml','.woff2':'font/woff2','.ico':'image/x-icon','.webp':'image/webp' };
http.createServer(async (req, res) => {
  const url = new URL(req.url, 'http://x');
  let p = normalize(url.pathname).replace(/^(\.\.[/\\])+/, '');
  if (p === '/' || p === '') p = '/index.html';
  const file = join(ROOT, p);
  if (existsSync(file) && statSync(file).isFile()) {
    const buf = await readFile(file);
    res.writeHead(200, { 'Content-Type': TYPES[extname(file)] || 'application/octet-stream' });
    return res.end(buf);
  }
  res.writeHead(404, { 'Content-Type': 'text/plain' });
  res.end('404 Not Found (strict server, no SPA fallback)');
}).listen(PORT, () => console.log('STRICT serving', ROOT, 'on', PORT));

