import { chromium } from 'playwright';
const BASE = 'http://localhost:4478'; // strict server
const EXEC = '/nix/store/zi4f80l169xlmivz8vja8wlphq74qqk0-chromium-125.0.6422.141/bin/chromium';
const browser = await chromium.launch({ executablePath: EXEC, args: ['--no-sandbox'] });
const ctx = await browser.newContext({ viewport: { width: 430, height: 900 } });

// Hash-route deep links on a NO-FALLBACK host.
const ROUTES = ['/dashboard','/trades','/trades/clients','/trades/clients/1','/trades/analytics',
  '/trades/terminal','/trades/quote','/trades/recurring','/property/tenants/1','/settings'];
console.log('--- direct hash-URL visits on STRICT server ---');
for (const path of ROUTES) {
  const page = await ctx.newPage();
  const errs = [];
  page.on('pageerror', e => errs.push(String(e).split('\n')[0]));
  await page.goto(BASE + '/#' + path, { waitUntil: 'networkidle', timeout: 20000 }).catch(e => errs.push('goto:' + e.message));
  await page.waitForTimeout(900);
  const body = (await page.evaluate(() => document.body.innerText).catch(() => '')) || '';
  const is404 = /404 Page Not Found/i.test(body);
  const len = body.replace(/\s+/g, ' ').trim().length;
  console.log(`${('/#'+path).padEnd(26)} ${is404 ? '*** APP-404 ***' : 'ok '} len=${String(len).padStart(5)}${errs.length ? '  ERR:' + errs[0] : ''}`);
  await page.close();
}

// Click flow: land on demo, go to settings, click Trades.
console.log('--- click flow: boot -> settings -> Trades ---');
const page = await ctx.newPage();
await page.goto(BASE + '/', { waitUntil: 'networkidle', timeout: 20000 }).catch(() => {});
await page.waitForTimeout(1000);
console.log('boot url:', page.url().replace(BASE, ''));
// navigate to settings via hash
await page.goto(BASE + '/#/settings', { waitUntil: 'networkidle', timeout: 20000 }).catch(() => {});
await page.waitForTimeout(1000);
const btn = page.getByText('Trades', { exact: true }).last();
if (await btn.count() > 0) {
  await btn.scrollIntoViewIfNeeded().catch(() => {});
  await btn.click().catch(e => console.log('click err', e.message));
  await page.waitForTimeout(1200);
  const body = (await page.evaluate(() => document.body.innerText).catch(() => '')) || '';
  console.log('after click url:', page.url().replace(BASE, ''));
  console.log('is app-404:', /404 Page Not Found/i.test(body));
  console.log('body head:', body.replace(/\s+/g, ' ').trim().slice(0, 140));
} else { console.log('Trades button NOT found'); }
await page.close();
await browser.close();

