import { chromium } from 'playwright';
const BASE = 'http://localhost:4477';
const EXEC = '/nix/store/zi4f80l169xlmivz8vja8wlphq74qqk0-chromium-125.0.6422.141/bin/chromium';
const browser = await chromium.launch({ executablePath: EXEC, args: ['--no-sandbox'] });
const ctx = await browser.newContext({ viewport: { width: 430, height: 900 } });

// 1) Direct-visit every trades route, check for 404 marker.
const ROUTES = ['/trades', '/trades/clients', '/trades/clients/1', '/trades/analytics',
  '/trades/terminal', '/trades/quote', '/trades/recurring'];
console.log('--- direct visits ---');
for (const path of ROUTES) {
  const page = await ctx.newPage();
  const errs = [];
  page.on('pageerror', e => errs.push(String(e).split('\n')[0]));
  await page.goto(BASE + path, { waitUntil: 'networkidle', timeout: 20000 }).catch(e => errs.push('goto:' + e.message));
  await page.waitForTimeout(900);
  const body = (await page.evaluate(() => document.body.innerText).catch(() => '')) || '';
  const is404 = /404 Page Not Found/i.test(body);
  const len = body.replace(/\s+/g, ' ').trim().length;
  console.log(`${path.padEnd(24)} ${is404 ? '*** 404 ***' : 'ok  '} len=${String(len).padStart(5)}${errs.length ? '  ERR:' + errs[0] : ''}`);
  await page.close();
}

// 2) Click flow: /settings -> Trades button.
console.log('--- click flow: settings -> Trades ---');
const page = await ctx.newPage();
await page.goto(BASE + '/settings', { waitUntil: 'networkidle', timeout: 20000 }).catch(() => {});
await page.waitForTimeout(900);
const btn = page.getByText('Trades', { exact: true }).last();
const found = await btn.count();
console.log('Trades button found:', found > 0);
if (found > 0) {
  await btn.scrollIntoViewIfNeeded().catch(() => {});
  await btn.click().catch(e => console.log('click err', e.message));
  await page.waitForTimeout(1200);
  const url = page.url();
  const body = (await page.evaluate(() => document.body.innerText).catch(() => '')) || '';
  console.log('after click url:', url.replace(BASE, ''));
  console.log('is 404:', /404 Page Not Found/i.test(body));
  console.log('body head:', body.replace(/\s+/g, ' ').trim().slice(0, 160));
}
await page.close();
await browser.close();
